// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/lottopollo.sol";

contract LottoPolloTest is Test {
    lottopollo public lottery;
    address public attacker = address(0xBAD);

    function setUp() public {
        lottery = new lottopollo();
    }

    function testPredictableRandomness() public {
        vm.startPrank(attacker);

        // Record current block timestamp
        uint256 currentTimestamp = block.timestamp;

        // Verify attacker can predict random number using public information
        uint256 predictedRandomNumber = currentTimestamp;
        uint256 generatedRandomNumber = lottery.randomGen();

        // Ensure generated "random" number matches predicted value
        assertEq(
            generatedRandomNumber, 
            predictedRandomNumber,
            "Random number should be predictable using block timestamp"
        );

        // Advance time and verify prediction consistency
        vm.warp(block.timestamp + 60); // 1 minute later

        // Predict new random number
        predictedRandomNumber = block.timestamp;
        generatedRandomNumber = lottery.randomGen();

        // Ensure prediction works after time advance
        assertEq(
            generatedRandomNumber, 
            predictedRandomNumber,
            "Random number should remain predictable after time change"
        );

        vm.stopPrank();
    }
}
